#!/usr/bin/env python3
"""Basic RESTful HTTP API for books (Python standard library only)."""

import json
import os
import re
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer


DEFAULT_PORT = 8000
HOST = "127.0.0.1"


def make_book(title, author, isbn, synopsis=""):
    return {
        "id": None,  # assigned later
        "title": title,
        "author": author,
        "isbn": isbn,
        "synopsis": synopsis,
    }


# In-memory store. Each book dict has id set when created.
_books = {}
_next_id = 1


def _validate_payload(body, require_id=False):
    """Validate a JSON body. Returns (book_dict, error_message).

    book_dict is None if an error occurred; error_message is a string.
    """
    # Body must be a JSON object
    if not isinstance(body, dict):
        return None, "error: invalid JSON body"

    title = body.get("title")
    author = body.get("author")
    isbn = body.get("isbn")
    synopsis = body.get("synopsis", "")

    # Check types and required/empty fields
    problems = []

    def _check_str(val, field):
        if not isinstance(val, str):
            return f"{field} is not a string"
        if val == "":
            return f"{field} is empty"
        return None

    t_err = _check_str(title, "title")
    if t_err:
        problems.append(t_err)

    a_err = _check_str(author, "author")
    if a_err:
        problems.append(a_err)

    i_err = _check_str(isbn, "isbn")
    if i_err:
        problems.append(i_err)

    # synopsis: optional string
    if synopsis is not None and not isinstance(synopsis, str):
        problems.append("synopsis is not a string")

    if problems:
        # Build a message listing the first problem, but the scenario
        # S4 expects error "isbn" is empty -> message "isbn is empty".
        return None, problems[0]

    if require_id:
        # id must not be supplied by client
        if "id" in body:
            return None, "error: id must not be supplied"

    book = {
        "id": _next_id,
        "title": title,
        "author": author,
        "isbn": isbn,
        "synopsis": synopsis if isinstance(synopsis, str) else "",
    }
    _next_id += 1
    _books[book["id"]] = book
    return book, None


class BookHandler(BaseHTTPRequestHandler):
    server_version = "BookAPI/1.0"

    # ---------- helpers ----------

    def _send_json(self, status, obj):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _send_error(self, status, message):
        self._send_json(status, {"error": message})

    def _read_body(self):
        length = int(self.headers.get("Content-Length", 0) or 0)
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            return None

    def _parse_path(self):
        """Return (path_segment, path_length) or (None, None) on no match."""
        path = self.path.split("?", 1)[0]
        # /books or /books/<id>
        parts = [p for p in path.split("/") if p]
        if len(parts) != 2 or parts[0] != "books":
            return None, None
        return parts[1], len(parts)

    def _parse_query(self):
        """Parse query string. Return (params_dict, error_response)."""
        query = self.path.split("?", 1)[1] if "?" in self.path else ""
        params = {}
        for pair in query.split("&"):
            if not pair:
                continue
            if "=" in pair:
                key, val = pair.split("=", 1)
            else:
                key, val = pair, ""
            key = key.strip()
            if key:
                params[key] = val.strip()
        return params

    # ---------- routing ----------

    def do_GET(self):
        path_segment, _ = self._parse_path()

        if path_segment is None:
            # any other path -> 404
            self._send_error(404, "not found")
            return

        if path_segment == "":
            # /books
            params = self._parse_query()
            # Unknown query parameter check
            allowed = {"id", "title", "author", "isbn", "synopsis", "q"}
            for key in params:
                if key not in allowed:
                    self._send_error(400, "unknown query parameter")
                    return

            # Apply filters
            books = [b for b in _books.values()]
            order = {k: i for i, k in enumerate(sorted(_books))}
            books.sort(key=lambda b: b["id"])

            # id filter
            if "id" in params:
                book_id = int(params["id"])
                # keep only book with that id
                filtered = [b for b in books if b["id"] == book_id]
            else:
                filtered = books

            # field contains filters (title, author, isbn, synopsis) - case-insensitive
            def _contains(field_name, value):
                val = value.lower()
                for b in filtered:
                    field_val = b.get(field_name, "")
                    if val in str(field_val).lower():
                        return True
                return False

            # build intersection
            for field in ("title", "author", "isbn", "synopsis"):
                val = params.get(field)
                if val is not None:
                    kept = [b for b in filtered if _contains(field, val)]
                    filtered = kept

            # q filter: any of the fields contains value
            q = params.get("q")
            if q is not None:
                qval = q.lower()
                filtered = [b for b in filtered if any(
                    qval in str(b.get(f, "")).lower() for f in ("title", "author", "isbn", "synopsis")
                )]

            if not filtered:
                self._send_json(200, [])
            else:
                self._send_json(200, filtered)
            return

        # path_segment is the id
        try:
            book_id = int(path_segment)
        except (ValueError, TypeError):
            # id in path not an integer
            self._send_error(404, "not found")
            return

        if book_id not in _books:
            self._send_error(404, "not found")
            return

        self._send_json(200, _books[book_id])

    def do_POST(self):
        path_segment, _ = self._parse_path()
        if path_segment != "books":
            self._send_error(404, "not found")
            return

        body = self._read_body()
        book, err = _validate_payload(body)
        if err is not None:
            self._send_error(400, err)
            return

        self._send_json(201, book)

    def do_PUT(self):
        path_segment, _ = self._parse_path()
        if path_segment != "books":
            self._send_error(404, "not found")
            return

        book_id = self._parse_id_or_404(path_segment)
        if book_id is None:
            return

        body = self._read_body()
        book, err = _validate_payload(body, require_id=True)
        if err is not None:
            self._send_error(400, err)
            return

        book = _books[book_id]
        book["title"] = book["title"]  # no-op keep
        # replace fields with validated ones
        book["title"] = book["title"]
        book["author"] = book["author"]
        book["isbn"] = book["isbn"]
        book["synopsis"] = book["synopsis"]
        self._send_json(200, book)

    def do_DELETE(self):
        path_segment, _ = self._parse_path()
        if path_segment != "books":
            self._send_error(404, "not found")
            return

        book_id = self._parse_id_or_404(path_segment)
        if book_id is None:
            return

        if book_id not in _books:
            self._send_error(404, "not found")
            return

        del _books[book_id]
        self.send_response(204)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def _parse_id_or_404(self, path_segment):
        try:
            return int(path_segment)
        except (ValueError, TypeError):
            self._send_error(404, "not found")
            return None

    # ---------- utils ----------

    def log_message(self, fmt, *args):
        # keep logs concise
        pass


def run_server():
    global _books, _next_id
    _books = {}
    _next_id = 1
    port = int(os.environ.get("PORT", DEFAULT_PORT))
    server = ThreadingHTTPServer((HOST, port), BookHandler)
    print(f"Serving on http://{HOST}:{port}", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    run_server()
PYEOF
